SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

CREATE DATABASE IF NOT EXISTS `db_kungfu_ai` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `db_kungfu_ai`;

-- ---------------------------------------------------------------------
-- Table structure and data for `reward_presets`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `reward_presets`;
CREATE TABLE `reward_presets` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `preset_code` varchar(50) NOT NULL,
  `preset_name` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `algorithm` enum('DQN','PPO','CURRICULUM_RL') NOT NULL DEFAULT 'DQN',
  `learning_rate` double NOT NULL DEFAULT 0.0025,
  `gamma` double NOT NULL DEFAULT 0.98,
  `epsilon_start` double NOT NULL DEFAULT 1,
  `epsilon_min` double NOT NULL DEFAULT 0.05,
  `epsilon_decay` double NOT NULL DEFAULT 0.89,
  `reward_forward_weight` double NOT NULL DEFAULT 5.5,
  `reward_upright_weight` double NOT NULL DEFAULT 2.5,
  `reward_gait_weight` double NOT NULL DEFAULT 3.5,
  `penalty_fall` double NOT NULL DEFAULT -45,
  `penalty_torque` double NOT NULL DEFAULT -0.04,
  `gravity` double NOT NULL DEFAULT 9.81,
  `ground_friction` double NOT NULL DEFAULT 0.88,
  `target_distance_m` double NOT NULL DEFAULT 10,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `preset_code` (`preset_code`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Table structure and data for `training_sessions`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `training_sessions`;
CREATE TABLE `training_sessions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `session_code` varchar(50) NOT NULL,
  `student_name` varchar(100) NOT NULL DEFAULT 'Mahasiswa Peserta Kompetisi',
  `session_title` varchar(150) NOT NULL,
  `algorithm` varchar(30) NOT NULL DEFAULT 'DQN',
  `preset_code` varchar(50) NOT NULL DEFAULT 'standar_seimbang',
  `learning_rate` double NOT NULL DEFAULT 0.0025,
  `gamma` double NOT NULL DEFAULT 0.98,
  `total_episodes` int(11) NOT NULL DEFAULT 0,
  `best_distance_m` double NOT NULL DEFAULT 0,
  `best_reward` double NOT NULL DEFAULT 0,
  `avg_distance_m` double NOT NULL DEFAULT 0,
  `avg_reward` double NOT NULL DEFAULT 0,
  `success_walk_count` int(11) NOT NULL DEFAULT 0,
  `fall_count` int(11) NOT NULL DEFAULT 0,
  `status` enum('active','completed','reset') NOT NULL DEFAULT 'active',
  `config_json` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `session_code` (`session_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Table structure and data for `episode_logs`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `episode_logs`;
CREATE TABLE `episode_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `session_id` int(11) NOT NULL DEFAULT 1,
  `episode_number` int(11) NOT NULL,
  `algorithm` varchar(30) NOT NULL DEFAULT 'DQN',
  `distance_m` double NOT NULL DEFAULT 0,
  `total_reward` double NOT NULL DEFAULT 0,
  `steps_count` int(11) NOT NULL DEFAULT 0,
  `duration_sec` double NOT NULL DEFAULT 0,
  `avg_torso_angle_deg` double NOT NULL DEFAULT 0,
  `avg_speed_ms` double NOT NULL DEFAULT 0,
  `epsilon` double NOT NULL DEFAULT 0,
  `loss_value` double NOT NULL DEFAULT 0,
  `termination_reason` varchar(120) NOT NULL DEFAULT 'Menabrak Box Penghalang',
  `reached_finish` tinyint(1) NOT NULL DEFAULT 0,
  `stage_label` varchar(100) NOT NULL DEFAULT 'Sudut NE | Tahap 1: Eksplorasi',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_session_ep` (`session_id`,`episode_number`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Table structure and data for `saved_models`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `saved_models`;
CREATE TABLE `saved_models` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `model_code` varchar(60) NOT NULL,
  `model_name` varchar(120) NOT NULL,
  `algorithm` varchar(30) NOT NULL DEFAULT 'DQN',
  `skill_level` varchar(60) NOT NULL DEFAULT 'Menengah (Bisa Lompat Box)',
  `trained_episodes` int(11) NOT NULL DEFAULT 1,
  `best_distance_m` double NOT NULL DEFAULT 0,
  `best_reward` double NOT NULL DEFAULT 0,
  `architecture_json` text NOT NULL,
  `weights_json` longtext NOT NULL,
  `notes` text DEFAULT NULL,
  `is_builtin` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `model_code` (`model_code`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Table structure and data for `competition_leaderboard`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `competition_leaderboard`;
CREATE TABLE `competition_leaderboard` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_name` varchar(100) NOT NULL,
  `student_nim` varchar(40) NOT NULL DEFAULT '-',
  `model_name` varchar(120) NOT NULL DEFAULT 'DQN Robot Agent',
  `algorithm` varchar(30) NOT NULL DEFAULT 'DQN',
  `episodes_trained` int(11) NOT NULL DEFAULT 1,
  `flags_captured` int(11) NOT NULL DEFAULT 0,
  `fastest_capture_sec` double NOT NULL DEFAULT 99.9,
  `jump_success_count` int(11) NOT NULL DEFAULT 0,
  `competition_score` double NOT NULL DEFAULT 0,
  `corner_mastery` varchar(80) NOT NULL DEFAULT '4/4 Sudut Random',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Table structure and data for `security_incidents`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `security_incidents`;
CREATE TABLE `security_incidents` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `incident_type` varchar(100) NOT NULL,
  `source_ip` varchar(45) NOT NULL,
  `request_uri` varchar(255) DEFAULT NULL,
  `payload_snippet` text DEFAULT NULL,
  `action_taken` varchar(50) DEFAULT 'Blocked',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- Table structure and data for `rl_demonstrations`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `rl_demonstrations`;
CREATE TABLE `rl_demonstrations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `demo_code` varchar(64) NOT NULL,
  `session_id` int(11) DEFAULT NULL,
  `title` varchar(160) NOT NULL,
  `demonstrator_name` varchar(100) NOT NULL DEFAULT 'Mahasiswa Demonstrator',
  `input_source` enum('webcam','keyboard','hybrid') NOT NULL DEFAULT 'webcam',
  `flag_corner_code` varchar(10) NOT NULL DEFAULT 'NE',
  `episode_count` int(11) NOT NULL DEFAULT 1,
  `total_steps` int(11) NOT NULL DEFAULT 0,
  `total_reward` double NOT NULL DEFAULT 0,
  `success_episodes` int(11) NOT NULL DEFAULT 0,
  `success_rate` double NOT NULL DEFAULT 0,
  `avg_confidence` double NOT NULL DEFAULT 0,
  `state_dim` int(11) NOT NULL DEFAULT 14,
  `action_dim` int(11) NOT NULL DEFAULT 9,
  `sample_rate_hz` double NOT NULL DEFAULT 8,
  `calibration_json` longtext DEFAULT NULL,
  `action_distribution_json` longtext DEFAULT NULL,
  `status` enum('recording','saved','archived') NOT NULL DEFAULT 'saved',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `demo_code` (`demo_code`),
  KEY `idx_demo_status_created` (`status`,`created_at`),
  KEY `fk_rl_demo_session` (`session_id`),
  CONSTRAINT `fk_rl_demo_session` FOREIGN KEY (`session_id`) REFERENCES `training_sessions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Table structure and data for `rl_demo_transitions`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `rl_demo_transitions`;
CREATE TABLE `rl_demo_transitions` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `demonstration_id` int(11) NOT NULL,
  `episode_id` int(11) NOT NULL DEFAULT 1,
  `step_number` int(11) NOT NULL,
  `timestamp_ms` bigint(20) NOT NULL,
  `state_json` longtext NOT NULL,
  `action` tinyint(4) NOT NULL,
  `confidence` double NOT NULL DEFAULT 1,
  `reward` double NOT NULL DEFAULT 0,
  `next_state_json` longtext NOT NULL,
  `done` tinyint(1) NOT NULL DEFAULT 0,
  `flag_corner` varchar(10) NOT NULL DEFAULT 'NE',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_demo_ep_step` (`demonstration_id`,`episode_id`,`step_number`),
  KEY `idx_demo_action` (`demonstration_id`,`action`),
  CONSTRAINT `fk_rl_trans_demo` FOREIGN KEY (`demonstration_id`) REFERENCES `rl_demonstrations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;







-- ---------------------------------------------------------------------
-- Table structure and data for `rl_training_sessions`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `rl_training_sessions`;
CREATE TABLE `rl_training_sessions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `training_code` varchar(64) NOT NULL,
  `demonstration_ids_json` longtext NOT NULL,
  `model_name` varchar(150) NOT NULL DEFAULT 'BC-Robot-Navigator',
  `architecture_json` longtext NOT NULL,
  `hyperparams_json` longtext NOT NULL,
  `normalization_json` longtext NOT NULL,
  `total_samples` int(11) NOT NULL DEFAULT 0,
  `train_samples` int(11) NOT NULL DEFAULT 0,
  `val_samples` int(11) NOT NULL DEFAULT 0,
  `epochs_planned` int(11) NOT NULL DEFAULT 50,
  `epochs_completed` int(11) NOT NULL DEFAULT 0,
  `final_loss` double DEFAULT NULL,
  `final_val_loss` double DEFAULT NULL,
  `final_accuracy` double DEFAULT NULL,
  `final_val_accuracy` double DEFAULT NULL,
  `confusion_matrix_json` longtext DEFAULT NULL,
  `class_distribution_json` longtext DEFAULT NULL,
  `status` enum('running','completed','cancelled','failed') NOT NULL DEFAULT 'running',
  `error_message` text DEFAULT NULL,
  `started_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `completed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `training_code` (`training_code`),
  KEY `idx_bc_train_status` (`status`,`started_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Table structure and data for `rl_training_metrics`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `rl_training_metrics`;
CREATE TABLE `rl_training_metrics` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `training_session_id` int(11) NOT NULL,
  `epoch` int(11) NOT NULL,
  `loss` double NOT NULL,
  `accuracy` double NOT NULL,
  `val_loss` double DEFAULT NULL,
  `val_accuracy` double DEFAULT NULL,
  `learning_rate` double DEFAULT NULL,
  `recorded_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_bc_metrics_epoch` (`training_session_id`,`epoch`),
  CONSTRAINT `fk_rl_metric_session` FOREIGN KEY (`training_session_id`) REFERENCES `rl_training_sessions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- Table structure and data for `rl_agent_models`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `rl_agent_models`;
CREATE TABLE `rl_agent_models` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `model_code` varchar(64) NOT NULL,
  `training_session_id` int(11) DEFAULT NULL,
  `model_name` varchar(150) NOT NULL,
  `version` varchar(32) NOT NULL DEFAULT '1.0.0',
  `algorithm` varchar(40) NOT NULL DEFAULT 'BEHAVIOR_CLONING',
  `state_dim` int(11) NOT NULL DEFAULT 14,
  `action_dim` int(11) NOT NULL DEFAULT 9,
  `architecture_json` longtext NOT NULL,
  `normalization_json` longtext NOT NULL,
  `metrics_json` longtext DEFAULT NULL,
  `file_path` varchar(255) NOT NULL,
  `file_size_bytes` int(11) NOT NULL DEFAULT 0,
  `checksum_sha256` varchar(64) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `model_code` (`model_code`),
  KEY `idx_bc_model_active` (`is_active`,`created_at`),
  KEY `fk_rl_model_train` (`training_session_id`),
  CONSTRAINT `fk_rl_model_train` FOREIGN KEY (`training_session_id`) REFERENCES `rl_training_sessions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Table structure and data for `rl_demo_annotations`
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS `rl_demo_annotations`;
CREATE TABLE `rl_demo_annotations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `demonstration_id` int(11) NOT NULL,
  `episode_id` int(11) NOT NULL DEFAULT 1,
  `step_start` int(11) NOT NULL DEFAULT 0,
  `step_end` int(11) NOT NULL DEFAULT 0,
  `label` varchar(80) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_anno_demo_ep` (`demonstration_id`,`episode_id`),
  CONSTRAINT `fk_rl_anno_demo` FOREIGN KEY (`demonstration_id`) REFERENCES `rl_demonstrations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
