INSERT INTO `reward_presets` (`id`, `preset_code`, `preset_name`, `description`, `algorithm`, `learning_rate`, `gamma`, `epsilon_start`, `epsilon_min`, `epsilon_decay`, `reward_forward_weight`, `reward_upright_weight`, `reward_gait_weight`, `penalty_fall`, `penalty_torque`, `gravity`, `ground_friction`, `target_distance_m`, `created_at`, `updated_at`) VALUES
(1, 'standar_seimbang', 'Kompetisi 1: DQN Standar (Navigasi Sudut + Hindari Box)', 'Rekomendasi utama kompetisi! Menyeimbangkan hadiah jalan kejar bendera di sudut acak (+5.5), bonus manuver menghindari box penghalang berwarna (+3.5), dan stabilitas gyro robot (+2.5).', 'DQN', 0.0025, 0.98, 1, 0.05, 0.89, 5.5, 2.5, 3.5, -45, -0.04, 9.81, 0.88, 10, '2026-11-14 18:46:48', '2026-11-14 18:46:48'),
(2, 'fokus_lari_cepat', 'Kompetisi 2: Speedrunner Rebut Bendera (Jalan Cepat Agresif)', 'Memberikan bobot kejar bendera sangat tinggi (+8.0) dan peluruhan eksplorasi cepat (0.86) agar Robot AI langsung berjalan cepat ke sudut bendera untuk mencetak rekor waktu tercepat.', 'DQN', 0.0035, 0.97, 1, 0.04, 0.86, 8, 1.8, 3, -35, -0.02, 9.81, 0.9, 10, '2026-11-14 18:46:48', '2026-11-14 18:46:48'),
(3, 'fokus_postur_tegak', 'Kompetisi 3: Spesialis Manuver Celah Box (Obstacle Master)', 'Memberikan hadiah tinggi (+5.5) saat Robot berhasil bermanuver halus melewati celah box kuning/biru menuju sudut bendera tanpa menabrak penghalang.', 'DQN', 0.0025, 0.99, 0.9, 0.05, 0.88, 5, 3, 5.5, -50, -0.05, 9.81, 0.88, 10, '2026-11-14 18:46:48', '2026-11-14 18:46:48'),
(4, 'lantai_es_licin', 'Kompetisi 4: Arena Tantangan Ekstrem (Lantai Licin)', 'Simulasi kompetisi dengan permukaan arena licin sehingga langkah kaki Robot menuntut kontrol keseimbangan gyro dan belokan halus.', 'CURRICULUM_RL', 0.0025, 0.98, 0.9, 0.05, 0.87, 5.5, 3.5, 4, -55, -0.05, 9.81, 0.55, 10, '2026-11-14 18:46:48', '2026-11-14 18:46:48');
